            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">Quick Check</text><text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">What was Russification, exactly?</text><rect x=\"80\" y=\"170\" width=\"940\" height=\"180\" fill=\"rgba(239,68,68,0.15)\" stroke=\"#ef4444\" stroke-width=\"2\" rx=\"12\"/><text x=\"120\" y=\"220\" fill=\"#ef4444\" font-size=\"26\" font-weight=\"bold\">Language Policy</text><text x=\"120\" y=\"265\" fill=\"#fff\" font-size=\"22\">Polish forbidden in secondary &amp; higher instruction</text><text x=\"120\" y=\"300\" fill=\"#fff\" font-size=\"22\">Russian compulsory for lectures, exams, official records</text><text x=\"120\" y=\"335\" fill=\"#888\" font-size=\"18\">Primary schools partially exempt but increasingly policed</text><rect x=\"80\" y=\"380\" width=\"940\" height=\"180\" fill=\"rgba(99,102,241,0.15)\" stroke=\"#6366f1\" stroke-width=\"2\" rx=\"12\"/><text x=\"120\" y=\"430\" fill=\"#6366f1\" font-size=\"26\" font-weight=\"bold\">Surveillance</text><text x=\"120\" y=\"475\" fill=\"#fff\" font-size=\"22\">Surprise inspections by Russian officials</text><text x=\"120\" y=\"510\" fill=\"#fff\" font-size=\"22\">Inspector Hornberg notorious in Warsaw schools</text><text x=\"120\" y=\"545\" fill=\"#888\" font-size=\"18\">Pupils required to recite Russian royal lineage on demand</text><rect x=\"80\" y=\"590\" width=\"940\" height=\"180\" fill=\"rgba(245,158,11,0.15)\" stroke=\"#f59e0b\" stroke-width=\"2\" rx=\"12\"/><text x=\"120\" y=\"640\" fill=\"#f59e0b\" font-size=\"26\" font-weight=\"bold\">Curriculum</text><text x=\"120\" y=\"685\" fill=\"#fff\" font-size=\"22\">Polish history excised; Russian history substituted</text><text x=\"120\" y=\"720\" fill=\"#fff\" font-size=\"22\">Polish Catholic identity discouraged</text><text x=\"120\" y=\"755\" fill=\"#888\" font-size=\"18\">Russian Orthodoxy quietly promoted in state schools</text><rect x=\"80\" y=\"800\" width=\"940\" height=\"230\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\" rx=\"12\"/><text x=\"120\" y=\"850\" fill=\"#10b981\" font-size=\"26\" font-weight=\"bold\">Education</text><text x=\"120\" y=\"895\" fill=\"#fff\" font-size=\"22\">Imperial University of Warsaw: Russian-only, men-only</text><text x=\"120\" y=\"930\" fill=\"#fff\" font-size=\"22\">No state-funded Polish-language schooling for women</text><text x=\"120\" y=\"965\" fill=\"#fff\" font-size=\"22\">Private &amp; clandestine networks filled the gap</text><text x=\"120\" y=\"1000\" fill=\"#888\" font-size=\"18\">Marie would meet every one of these constraints in turn</text></svg>",
