          svg: `<svg viewBox="0 0 1100 1100" xmlns="http://www.w3.org/2000/svg"><rect x="0" y="0" width="1100" height="1100" fill="#1a1a2e"/><text x="550" y="60" text-anchor="middle" fill="#ffd700" font-weight="bold" font-size="36">The Curie Dynasty</text><text x="550" y="105" text-anchor="middle" fill="#888" font-size="22">Four Nobels, two generations, two paths</text><rect x="80" y="160" width="940" height="180" rx="20" fill="rgba(99,102,241,0.12)" stroke="#6366f1" stroke-width="2"/><text x="120" y="215" fill="#6366f1" font-weight="bold" font-size="26">Generation 1 — Marie and Pierre</text><text x="120" y="260" fill="#fff" font-size="22">Marie Curie: Physics 1903, Chemistry 1911</text><text x="120" y="295" fill="#fff" font-size="22">Pierre Curie: Physics 1903</text><text x="120" y="335" fill="#888" font-size="18">Three prizes between them</text><rect x="80" y="370" width="940" height="180" rx="20" fill="rgba(139,92,246,0.12)" stroke="#8b5cf6" stroke-width="2"/><text x="120" y="425" fill="#8b5cf6" font-weight="bold" font-size="26">Generation 2 — Irène and Frédéric</text><text x="120" y="470" fill="#fff" font-size="22">Irène Joliot-Curie: Chemistry 1935</text><text x="120" y="505" fill="#fff" font-size="22">Frédéric Joliot: Chemistry 1935 (shared)</text><text x="120" y="545" fill="#888" font-size="18">For the discovery of artificial radioactivity</text><rect x="80" y="580" width="940" height="180" rx="20" fill="rgba(236,72,153,0.12)" stroke="#ec4899" stroke-width="2"/><text x="120" y="635" fill="#ec4899" font-weight="bold" font-size="26">The Other Daughter — Ève</text><text x="120" y="680" fill="#fff" font-size="22">Pianist, journalist, biographer</text><text x="120" y="715" fill="#fff" font-size="22">Wrote "Madame Curie" (1937), 3+ million copies</text><text x="120" y="755" fill="#888" font-size="18">Husband Henry Labouisse accepted UNICEF Peace 1965</text><rect x="80" y="790" width="940" height="240" rx="20" fill="rgba(16,185,129,0.12)" stroke="#10b981" stroke-width="2"/><text x="120" y="845" fill="#10b981" font-weight="bold" font-size="26">Generation 3 — Hélène and Pierre Joliot</text><text x="120" y="890" fill="#fff" font-size="22">Hélène Langevin-Joliot: nuclear physicist, b. 1927</text><text x="120" y="925" fill="#fff" font-size="22">Pierre Joliot: biochemist of photosynthesis, b. 1932</text><text x="120" y="965" fill="#fff" font-size="22">Hélène married Michel Langevin — Paul's grandson</text><text x="120" y="1005" fill="#888" font-size="18">The 1911 scandal closed by a third-generation marriage</text></svg>`,
